public class Main {
    static List<String> splitTop(String s) {
        List<String> parts = new ArrayList<>(); int depth=0, start=0;
        for (int i=0;i<s.length();i++) {
            char c=s.charAt(i);
            if (c=='[') depth++; else if (c==']') depth--;
            else if (c==',' && depth==0) { parts.add(s.substring(start,i).trim()); start=i+1; }
        }
        parts.add(s.substring(start).trim()); return parts;
    }
    static int[] parseArray(String s) {
        String inner=s.trim().substring(1,s.trim().length()-1).trim();
        if (inner.isEmpty()) return new int[0];
        String[] p=inner.split(","); int[] a=new int[p.length];
        for(int i=0;i<p.length;i++) a[i]=Integer.parseInt(p[i].trim());
        return a;
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String line=br.readLine().trim();
        String outer=line.substring(1,line.length()-1);
        List<String> parts=splitTop(outer);
        int[] flowerbed=parseArray(parts.get(0));
        int n=Integer.parseInt(parts.get(1).trim());
        System.out.println(new Solution().canPlaceFlowers(flowerbed,n));
    }
}

